import json, html, os, shutil
from pathlib import Path
from datetime import datetime, timezone
ROOT=Path(__file__).resolve().parents[1]
def esc(s): return html.escape(str(s),quote=True)
def build():
    config=json.loads((ROOT/'config.json').read_text()); data=json.loads((ROOT/'data/offers.json').read_text(encoding='utf-8'))
    if config['affiliate_enabled']: raise ValueError('Affiliation non activable sans intégration approuvée')
    dest=ROOT/'dist';dest.mkdir(exist_ok=True)
    for p in (ROOT/'static').iterdir(): shutil.copy(p,dest/p.name)
    cards=[];now=datetime.now(timezone.utc)
    for d in data['offers']:
        if datetime.fromisoformat(d['valid_until'])<=now: continue
        price='Jeu offert' if d['kind']=='free' else esc(d['price'])+' $ US'
        badge='À récupérer' if d['kind']=='free' else '−'+str(d['discount'])+' %'
        cards.append(f'''<article class="card" data-kind="{d['kind']}" data-until="{esc(d['valid_until'])}"><div class="cardtop"><span>{badge}</span><small>{esc(d['source'])}</small></div><h2>{esc(d['title'])}</h2><p class="store">{esc(d['store'])}</p><p class="price">{price}</p><p>{esc(d['region'])}</p><p class="expiry">Fin : {esc(d['expiration_label'])}</p><small>Relevé API : {esc(d['checked_at'])}</small><a class="cta" rel="noopener" href="{esc(d['url'])}">Consulter l’offre ↗</a></article>''')
    state='Collecte complète' if all(s['ok'] for s in data['sources'].values()) else 'Collecte partielle : une source est indisponible'
    canonical=config['site_url'].rstrip('/')
    meta=f'<link rel="canonical" href="{esc(canonical)}/">' if canonical else '<meta name="robots" content="noindex">'
    page=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkpoint — jeux offerts & fortes promotions</title><meta name="description" content="Les jeux temporairement offerts et les promotions PC de 70 % et plus. Sources, dates et limites affichées pour chaque offre.">{meta}<link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><header><a class="brand" href="./">✦ CHECKPOINT<span>Le bon jeu. Au bon moment.</span></a><nav><a href="#offres">Les offres</a><a href="#methode">Notre méthode</a></nav></header><main><section class="hero"><p class="eyebrow">LE RADAR DES JOUEURS ÉCONOMES</p><h1>Plus de jeux.<br><em>Moins de dépenses.</em></h1><p>Jeux offerts pour une durée limitée et promotions d’au moins 70 %. Une sélection issue d’API autorisées, sans abonnement.</p><div class="status">● {state} · <time>{esc(data['generated_at'])}</time></div></section><section id="offres"><div class="sectionhead"><h2>À saisir maintenant</h2><span id="count">{len(cards)} offres</span></div><div class="filters"><label>Rechercher un jeu<input id="search" type="search" placeholder="Un titre, une plateforme…"></label><label>Type d’offre<select id="kind"><option value="all">Toutes les offres</option><option value="free">Jeux offerts</option><option value="sale">Promotions</option></select></label></div><p class="notice">Les promotions sont en dollars US. Les sources ne garantissent pas l’activation en France. Vérifie le prix final, les conditions et la région avant de récupérer ou d’acheter.</p><div class="grid">{''.join(cards)}</div><p id="empty" {'hidden' if cards else ''}>Aucune offre récente à afficher. La prochaine collecte pourra en ajouter.</p><noscript>La recherche nécessite JavaScript. Les offres restent consultables ; vérifie l’heure de relevé avant de cliquer.</noscript></section><section id="methode" class="method"><p class="eyebrow">UNE SÉLECTION TRANSPARENTE</p><h2>Une source à chaque offre.</h2><p>Nos relevés proviennent de <a href="https://www.gamerpower.com/api-read">GamerPower</a> et de <a href="https://apidocs.cheapshark.com/">CheapShark</a>. Il s’agit de signalements d’agrégateurs, pas d’une vérification directe en boutique. Les offres de plus de 12 heures sont masquées lorsque JavaScript est actif. Une date absente reste « non communiquée ». Nous ne convertissons pas les dollars en euros.</p><p>GamerPower fournit les jeux complets ; les bonus et accès bêta sont exclus. Une offre peut demander un compte, des étapes de récupération ou être limitée en quantité. Les instructions sont sur la page source.</p></section></main><footer><strong>CHECKPOINT</strong><p>Données : <a href="https://www.gamerpower.com/">GamerPower</a> et <a href="https://www.cheapshark.com/">CheapShark</a>. Aucun partenariat revendiqué.</p><p>Affiliation du site désactivée. Les liens CheapShark conservent leur attribution obligatoire au fournisseur.</p><p>Aucun cookie, publicité, analyse d’audience ou formulaire ajouté. L’hébergeur peut conserver ses journaux techniques.</p><p>{esc(config['publisher'] or 'Prépublication : identité de l’éditeur à renseigner')} · {esc(config['contact'] or 'Contact à renseigner avant publication publique')}</p><a href="health.json">État des collectes</a></footer></body></html>'''
    (dest/'index.html').write_text(page,encoding='utf-8')
    (dest/'health.json').write_text(json.dumps({'generated_at':data['generated_at'],'sources':data['sources'],'maximum_age_hours':12}),encoding='utf-8')
    (dest/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nSitemap: '+canonical+'/sitemap.xml\n' if canonical else 'Disallow: /\n'))
    if canonical:(dest/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>'+esc(canonical)+'/</loc></url></urlset>')
    print(f'Built {len(cards)} offers')
if __name__=='__main__':build()
